<header class="page-heading"><div><p class="eyebrow">A HOME FOR EVERY SUBJECT</p><h1>My decks<span class="heading-dot">.</span></h1><p>Organize your ideas. Build knowledge that stays with you.</p></div><a class="btn btn-primary" href="<?= e(url('/decks/create')) ?>"><?= icon('plus') ?> Create a deck</a></header>
<form action="<?= e(url('/decks')) ?>" method="get" class="filter-bar"><div class="search-field"><?= icon('search') ?><label class="sr-only" for="deck-query">Search your decks</label><input type="search" id="deck-query" name="q" maxlength="200" value="<?= e($query) ?>" placeholder="Find a deck by title or subject"></div><div class="filter-select"><label class="sr-only" for="subject">Subject</label><select id="subject" name="subject"><option value="">All subjects</option><?php foreach ($subjects as $item): ?><option value="<?= e($item) ?>" <?= $subject === $item ? 'selected' : '' ?>><?= e($item ?: 'General') ?></option><?php endforeach; ?></select></div><button class="btn btn-secondary" type="submit">Filter decks</button><?php if ($query !== '' || $subject !== ''): ?><a href="<?= e(url('/decks')) ?>" class="text-link">Clear filters</a><?php endif; ?></form>
<div class="section-caption"><span><?= count($decks) ?> <?= count($decks) === 1 ? 'deck' : 'decks' ?><?= ($query !== '' || $subject !== '') ? ' found' : ' in your collection' ?></span><span>One subject. A little more clarity.</span></div>
<?php if (!$decks): ?><section class="panel empty-state"><span class="empty-icon"><?= icon('decks',36) ?></span><h2><?= ($query !== '' || $subject !== '') ? 'No decks match these filters' : 'Good things start with a first deck' ?></h2><p><?= ($query !== '' || $subject !== '') ? 'Try another title or subject, or clear your filters to see the whole collection.' : 'From a tricky definition to a whole new language, give what you’re learning a place to grow.' ?></p><a class="btn btn-primary" href="<?= e(url(($query !== '' || $subject !== '') ? '/decks' : '/decks/create')) ?>"><?= ($query !== '' || $subject !== '') ? 'Show all decks' : 'Create your first deck' ?></a></section>
<?php else: ?><section class="deck-grid" aria-label="Deck collection"><?php foreach ($decks as $deck): ?><article class="deck-card" style="--deck-color: <?= e($deck['color']) ?>"><div class="deck-card-top"><span class="deck-color"><?= icon('decks',25) ?></span><span class="badge"><?= e($deck['subject'] ?: 'General') ?></span></div><h2><a href="<?= e(url('/decks/' . ((int) $deck['id']))) ?>"><?= e($deck['title']) ?></a></h2><p><?= e(excerpt($deck['description'] ?: 'A little curiosity, a lot to discover.')) ?></p><div class="deck-meta"><span><?= icon('cards',15) ?> <?= (int) $deck['card_count'] ?> cards</span><span><?= icon('clock',15) ?> <?= (int) $deck['due_count'] ?> due</span></div><div class="progress-caption"><span>Mastery</span><strong><?= (int) $deck['progress'] ?>%</strong></div><div class="progress-track" role="progressbar" aria-label="<?= e($deck['title']) ?> mastery" aria-valuemin="0" aria-valuemax="100" aria-valuenow="<?= (int) $deck['progress'] ?>"><span class="progress-fill" style="width: <?= (int) $deck['progress'] ?>%"></span></div><div class="deck-footer"><a class="text-link" href="<?= e(url('/decks/' . ((int) $deck['id']))) ?>">Open deck <?= icon('arrow',16) ?></a><form method="post" action="<?= e(url('/study/start')) ?>"><?= csrf_field() ?><input type="hidden" name="deck_id" value="<?= (int) $deck['id'] ?>"><input type="hidden" name="mode" value="due"><button class="btn btn-small btn-secondary" <?= (int) $deck['due_count'] === 0 ? 'disabled' : '' ?>><?= icon('study',15) ?> Study</button></form></div></article><?php endforeach; ?></section><?php endif; ?>
